function maxSelectedElements(nums) {
  nums.sort((a, b) => a - b);
  const dp = new Map();
  let best = 0;
  for (const num of nums) {
    const raised = (dp.get(num) ?? 0) + 1;
    const kept = (dp.get(num - 1) ?? 0) + 1;
    dp.set(num + 1, Math.max(dp.get(num + 1) ?? 0, raised));
    dp.set(num, Math.max(dp.get(num) ?? 0, kept));
    best = Math.max(best, raised, kept);
  }
  return best;
}

