function maxSelectedElements(nums) {
  // Try every choice of which elements to raise, then find the longest run of consecutive distinct values.
  let best = 0;
  for (let mask = 0; mask < (1 << nums.length); mask++) {
    const values = new Set(nums.map((v, i) => (mask >> i) & 1 ? v + 1 : v));
    for (const v of values) {
      if (values.has(v - 1)) continue;
      let length = 1;
      while (values.has(v + length)) length++;
      best = Math.max(best, length);
    }
  }
  return best;
}

