function generate(rand, size) {
  if (size === 'small') {
    const n = 1 + Math.floor(rand() * 8);
    const span = 1 + Math.floor(rand() * 12);
    const low = rand() < 0.2 ? 1000000 - span : 1;
    return [Array.from({ length: n }, () => low + Math.floor(rand() * span))];
  }
  const n = 2000;
  const span = 1500 + Math.floor(rand() * 3000);
  const low = 1 + Math.floor(rand() * (1000000 - span));
  const nums = [];
  for (let i = 0; i < n; i++) nums.push(rand() < 0.05 ? 1 + Math.floor(rand() * 1000000) : low + Math.floor(rand() * span));
  return [nums];
}
